VFT-01.code:
@layer components {
  .profile-card {
    border: var(--shelf-border-width) solid var(--shelf-color-border);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-space-md);
    background: var(--shelf-color-surface);
  }

  .profile-card-title {
    font-size: var(--shelf-font-size-lg);
    font-weight: var(--shelf-font-weight-bold);
    color: var(--shelf-color-text-primary);
  }

  .profile-card-subtitle {
    font-size: var(--shelf-font-size-sm);
    color: var(--shelf-color-text-secondary);
  }

  .profile-card-skeleton-bar {
    height: var(--shelf-skeleton-height);
    background: var(--shelf-color-skeleton);
    border-radius: var(--shelf-radius-sm);
    width: var(--shelf-skeleton-bar-width, 100%);
  }

  .profile-card-skeleton-bar--short {
    --shelf-skeleton-bar-width: 60%;
  }

  @keyframes shimmer {
    from {
      opacity: var(--shelf-motion-shimmer-opacity-from);
    }
    to {
      opacity: var(--shelf-motion-shimmer-opacity-to);
    }
  }

  .profile-card-skeleton-bar {
    animation: shimmer var(--shelf-motion-duration-md) var(--shelf-motion-easing-standard) infinite alternate;
  }
}

