VFT-C1.code:
@layer components {
  .status-badge {
    display: inline-flex;
    align-items: center;
    padding-block: var(--shelf-space-xs);
    padding-inline: var(--shelf-space-sm);
    border-radius: var(--shelf-radius-full);
    font-size: var(--shelf-font-size-xs);
    font-weight: var(--shelf-font-weight-medium);
    background: var(--shelf-bgColor-default);
    color: var(--shelf-fgColor-muted);
  }

  .status-badge[data-status="read"] {
    background: var(--shelf-bgColor-status-read);
    color: var(--shelf-fgColor-status-read);
  }

  .status-badge[data-status="reading"] {
    background: var(--shelf-bgColor-status-reading);
    color: var(--shelf-fgColor-status-reading);
  }

  .status-badge[data-status="want-to-read"] {
    background: var(--shelf-bgColor-status-want-to-read);
    color: var(--shelf-fgColor-status-want-to-read);
  }
}
